onConnect: (socket, req, send) => {
  // Attach user agent info
  socket.userAgent = req.headers['user-agent'];

  // Reject certain clients
  if (isBot(socket.userAgent)) {
    socket.close();
    return;
  }

  // Send welcome
  send({ connected: true, clientId: socket.id });
}

